<?php
/** Advanced UX: psychology and UX laws, metrics and experiments, ethics and dark patterns, service design and strategy. */

return [
    'id' => 'ux-advanced', 'family' => 'ux', 'after' => 'ux-intermediate', 'categories' => ['design'],
    'title' => L('UX: livello avanzato', 'UX Advanced'), 'short' => L('UX avanzato', 'UX Advanced'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Psicologia e leggi della UX, metriche e A/B test, etica e dark pattern, service design e strategia: la UX che guida le decisioni di prodotto.', 'Psychology and the laws of UX, metrics and A/B tests, ethics and dark patterns, service design and strategy: UX that drives product decisions.'),
    'lessons' => [
        lesson('laws', L('Psicologia e leggi della UX', 'Psychology and the laws of UX'), [
            P('Alcune leggi della psicologia aiutano a prevedere il comportamento. **Legge di Hick**: più opzioni ci sono, più tempo serve per scegliere, quindi raggruppa e riduci. **Legge di Fitts**: un bersaglio grande e vicino si raggiunge prima, quindi i pulsanti principali vanno grandi e a portata. **Legge di Jakob**: gli utenti passano la maggior parte del tempo su altri siti e si aspettano che il tuo funzioni allo stesso modo.', 'Some laws from psychology help predict behaviour. **Hick’s law**: the more options, the longer it takes to choose, so group and reduce. **Fitts’s law**: a large, nearby target is reached faster, so main buttons should be big and within reach. **Jakob’s law**: users spend most of their time on other sites and expect yours to work the same way.'),
            P('Il **carico cognitivo** è lo sforzo mentale richiesto: la memoria di lavoro tiene pochi elementi alla volta, per questo si spezzano le informazioni in blocchi (**chunking**, come un IBAN scritto a gruppi di quattro). L’**effetto von Restorff** rende memorabile ciò che spicca, l’**effetto della posizione seriale** fa ricordare meglio il primo e l’ultimo elemento di una lista.', '**Cognitive load** is the mental effort required: working memory holds only a few items at a time, so information is split into blocks (**chunking**, like an IBAN written in groups of four). The **von Restorff effect** makes what stands out memorable, the **serial position effect** makes the first and last items of a list easier to remember.'),
        ], [
            Q('l1', L('Che cosa dice la legge di Hick?', 'What does Hick’s law say?'), [L('Più opzioni, più tempo per scegliere', 'More options, more time to choose'), L('I bersagli grandi sono più lenti', 'Large targets are slower'), L('Gli utenti leggono tutto', 'Users read everything'), L('Il blu è il colore più cliccato', 'Blue is the most clicked colour')], 0, L('Riduci e raggruppa.', 'Reduce and group.')),
            Q('l2', L('Quale legge giustifica pulsanti principali grandi e vicini?', 'Which law justifies big, nearby main buttons?'), [L('Legge di Fitts', 'Fitts’s law'), L('Legge di Hick', 'Hick’s law'), L('Legge di Jakob', 'Jakob’s law'), L('Legge di Murphy', 'Murphy’s law')], 0, L('Dimensione e distanza.', 'Size and distance.')),
            Q('l3', L('Perché un numero di telefono si mostra a gruppi?', 'Why is a phone number shown in groups?'), [L('Il chunking riduce il carico cognitivo', 'Chunking reduces cognitive load'), L('Per occupare più spazio', 'To take up more space'), L('Per motivi legali', 'For legal reasons'), L('Per renderlo più difficile', 'To make it harder')], 0, L('Blocchi più facili da tenere a mente.', 'Blocks easier to hold in mind.')),
        ], task('text', L('Un menu ha 14 voci tutte allo stesso livello. Scrivi due interventi, uno per riga con `-`, citando la **legge di Hick** e il **chunking** o i raggruppamenti.', 'A menu has 14 items all at the same level. Write two fixes, one per line with `-`, mentioning **Hick’s law** and **chunking** or grouping.'), "- \n- ", [re('^-\s*\S.*\n-\s*\S', L('Due interventi', 'Two fixes')), re('hick', L('Cita Hick', 'Mentions Hick')), re('chunk|grupp|group|categor', L('Raggruppa', 'Groups'))], '', "- per la legge di Hick tengo in vista solo le 5 voci più usate\n- raggruppo le altre in categorie (chunking) dentro un menu Altro"), [
            dMatch(pMatch(), [[L('Legge di Hick', 'Hick’s law'), L('Meno scelte, decisioni rapide', 'Fewer choices, quick decisions')], [L('Legge di Fitts', 'Fitts’s law'), L('Bersagli grandi e vicini', 'Big, nearby targets')], [L('Legge di Jakob', 'Jakob’s law'), L('Funziona come gli altri siti', 'Works like other sites')], ['Chunking', L('Informazioni a blocchi', 'Information in blocks')], ['Von Restorff', L('Si ricorda ciò che spicca', 'What stands out is remembered')]], L('Le leggi della UX.', 'The laws of UX.')),
            dFlash(pFlash(), [[L('La memoria di lavoro tiene pochi elementi alla volta', 'Working memory holds few items at a time'), true], [L('Più opzioni rendono sempre la scelta più veloce', 'More options always make choosing faster'), false], [L('Il primo e l’ultimo di una lista si ricordano meglio', 'The first and last of a list are remembered best'), true], [L('Gli utenti preferiscono interfacce mai viste', 'Users prefer never-seen-before interfaces'), false]], L('La mente dell’utente.', 'The user’s mind.')),
        ]),
        lesson('metrics', L('Metriche ed esperimenti', 'Metrics and experiments'), [
            P('La UX avanzata misura i risultati. Il framework **HEART** di Google propone cinque aree: **Happiness** (soddisfazione), **Engagement** (coinvolgimento), **Adoption** (nuovi utenti di una funzione), **Retention** (chi torna), **Task success** (compiti riusciti, tempo, errori). Per ognuna si fissano obiettivo, segnale e metrica.', 'Advanced UX measures outcomes. Google’s **HEART** framework proposes five areas: **Happiness** (satisfaction), **Engagement**, **Adoption** (new users of a feature), **Retention** (who comes back), **Task success** (completed tasks, time, errors). For each you set a goal, a signal and a metric.'),
            P('Un **funnel** mostra quanti utenti passano da un passo all’altro (visita, carrello, pagamento): il calo più forte indica dove intervenire. Un **A/B test** confronta due versioni su gruppi casuali; serve un’**ipotesi** chiara, una sola metrica principale e abbastanza utenti perché la differenza sia **statisticamente significativa**, non un caso.', 'A **funnel** shows how many users move from one step to the next (visit, cart, payment): the biggest drop shows where to act. An **A/B test** compares two versions on random groups; it needs a clear **hypothesis**, a single primary metric and enough users for the difference to be **statistically significant**, not chance.'),
            C('Funnel di acquisto
Visita prodotto   10.000  100%
Aggiunta carrello  2.400   24%
Inizio checkout    1.900   19%
Pagamento            600    6%   ← il calo più grande: checkout → pagamento', 'text'),
        ], [
            Q('m1', L('Che cosa misura la R di HEART?', 'What does the R in HEART measure?'), [L('Quanti utenti tornano', 'How many users come back'), L('Le recensioni negative', 'Negative reviews'), L('La velocità di risposta', 'Response speed'), L('I ricavi pubblicitari', 'Ad revenue')], 0, L('Retention.', 'Retention.')),
            Q('m2', L('A che cosa serve un funnel?', 'What is a funnel for?'), [L('Trovare il passo dove si perdono più utenti', 'Finding the step where most users drop'), L('Filtrare il caffè', 'Filtering coffee'), L('Contare i pixel', 'Counting pixels'), L('Ordinare i prodotti', 'Sorting products')], 0, L('Il calo più forte.', 'The biggest drop.')),
            Q('m3', L('Che cosa serve a un A/B test affidabile?', 'What does a reliable A/B test need?'), [L('Ipotesi chiara e abbastanza utenti', 'A clear hypothesis and enough users'), L('Tante metriche scelte dopo il test', 'Many metrics chosen after the test'), L('Due utenti per gruppo', 'Two users per group'), L('Fermarlo appena vince una versione', 'Stopping as soon as one version wins')], 0, L('Niente risultati per caso.', 'No results by chance.')),
        ], task('text', L('Scrivi un’ipotesi per un A/B test sul checkout nel formato `Se ..., allora ..., perché ...` (o `If ..., then ..., because ...`), con una **metrica** da misurare.', 'Write an A/B test hypothesis for the checkout in the format `If ..., then ..., because ...`, with a **metric** to measure.'), '', [re('^(se|if)\b', L('Inizia con il cambiamento', 'Starts with the change')), re('(allora|then)', L('Dice il risultato atteso', 'States the expected result')), re('(perché|perche|because)', L('Spiega il motivo', 'Explains why')), re('%|tasso|rate|convers|complet|tempo|time', L('C’è una metrica', 'There is a metric'))], '', 'Se permettiamo il pagamento come ospite, allora il tasso di completamento del checkout salirà, perché molti abbandonano alla richiesta di registrazione.'), [
            dMatch(pMatch(), [['Happiness', L('Soddisfazione', 'Satisfaction')], ['Engagement', L('Coinvolgimento', 'Involvement')], ['Adoption', L('Nuovi utenti di una funzione', 'New users of a feature')], ['Retention', L('Chi torna', 'Who comes back')], ['Task success', L('Compiti riusciti', 'Completed tasks')]], L('Il framework HEART.', 'The HEART framework.')),
            dFlash(pFlash(), [[L('Un A/B test usa gruppi casuali', 'An A/B test uses random groups'), true], [L('Si può scegliere la metrica dopo aver visto i dati', 'You can pick the metric after seeing the data'), false], [L('Il calo più forte del funnel indica dove agire', 'The funnel’s biggest drop shows where to act'), true], [L('Pochi utenti bastano sempre per un risultato certo', 'Few users always suffice for a certain result'), false]], L('Decidere con i dati.', 'Deciding with data.')),
        ]),
        lesson('ethics', L('Etica e dark pattern', 'Ethics and dark patterns'), [
            P('I **dark pattern** (o design ingannevole) sono interfacce costruite per far fare alle persone cose che non vogliono: il **roach motel** (abbonarsi in un clic, disdire con dieci passaggi), il **confirmshaming** (“No grazie, preferisco pagare di più”), le **caselle già spuntate**, i **costi nascosti** che compaiono all’ultimo passo, la **falsa urgenza** (“solo 2 rimasti!” sempre).', '**Dark patterns** (or deceptive design) are interfaces built to make people do things they do not want: the **roach motel** (subscribe in one click, cancel in ten steps), **confirmshaming** (“No thanks, I prefer paying more”), **pre-ticked boxes**, **hidden costs** appearing at the last step, **fake urgency** (“only 2 left!” always).'),
            P('Oltre a danneggiare la fiducia, molti sono **illegali** in Europa: il GDPR vuole consenso libero e caselle non spuntate, il **Digital Services Act** vieta le interfacce ingannevoli sulle piattaforme, e le norme sui consumatori chiedono di poter disdire facilmente. Il buon design rende **facile quanto entrare** anche uscire.', 'Besides damaging trust, many are **illegal** in Europe: the GDPR requires freely given consent and unticked boxes, the **Digital Services Act** bans deceptive interfaces on platforms, and consumer rules require easy cancellation. Good design makes **leaving as easy as joining**.'),
            Tip('Una domanda utile in ogni revisione: “L’utente sarebbe contento se sapesse esattamente perché abbiamo progettato così?”', 'A useful question in every review: “Would the user be happy if they knew exactly why we designed it this way?”'),
        ], [
            Q('e1', L('Che cos’è il confirmshaming?', 'What is confirmshaming?'), [L('Colpevolizzare chi rifiuta un’offerta', 'Guilt-tripping people who decline an offer'), L('Confermare un ordine due volte', 'Confirming an order twice'), L('Un messaggio di benvenuto', 'A welcome message'), L('Un tipo di captcha', 'A kind of captcha')], 0, L('“No grazie, odio risparmiare”.', '“No thanks, I hate saving”.')),
            Q('e2', L('Che cos’è il roach motel?', 'What is the roach motel?'), [L('Facile entrare, difficile uscire', 'Easy to get in, hard to get out'), L('Un hotel per sviluppatori', 'A hotel for developers'), L('Una pagina 404 simpatica', 'A funny 404 page'), L('Un menu a scomparsa', 'A collapsing menu')], 0, L('Abbonamenti trappola.', 'Trap subscriptions.')),
            Q('e3', L('Che cosa dice il GDPR sulle caselle di consenso?', 'What does the GDPR say about consent boxes?'), [L('Non devono essere già spuntate', 'They must not be pre-ticked'), L('Devono essere già spuntate', 'They must be pre-ticked'), L('Devono essere nascoste', 'They must be hidden'), L('Non dice nulla', 'It says nothing')], 0, L('Consenso libero e attivo.', 'Free, active consent.')),
        ], task('text', L('Riscrivi questo pulsante di rifiuto in modo onesto e neutro: “No grazie, non mi interessa diventare più bravo”.', 'Rewrite this decline button in an honest, neutral way: “No thanks, I don’t want to get better”.'), '', [re('^(no|non ora|not now|salta|skip|più tardi|later)', L('Un rifiuto semplice', 'A simple decline')), re('^(?!.*(bravo|better|preferisco|prefer)).+$', L('Niente colpevolizzazione', 'No guilt-tripping'))], '', 'No, grazie'), [
            dMatch(pMatch(), [['Roach motel', L('Disdetta difficile', 'Hard cancellation')], ['Confirmshaming', L('Colpevolizza chi rifiuta', 'Shames who declines')], [L('Costi nascosti', 'Hidden costs'), L('Spese all’ultimo passo', 'Fees at the last step')], [L('Falsa urgenza', 'Fake urgency'), L('“Solo 2 rimasti!” sempre', '“Only 2 left!” always')], [L('Caselle spuntate', 'Pre-ticked boxes'), L('Consenso non libero', 'Consent not freely given')]], L('Riconoscere l’inganno.', 'Spotting deception.')),
            dFlash(pFlash(), [[L('Il Digital Services Act vieta interfacce ingannevoli', 'The Digital Services Act bans deceptive interfaces'), true], [L('I dark pattern aumentano la fiducia nel tempo', 'Dark patterns increase trust over time'), false], [L('Disdire dovrebbe essere facile quanto abbonarsi', 'Cancelling should be as easy as subscribing'), true], [L('Una casella già spuntata è un consenso valido per il GDPR', 'A pre-ticked box is valid GDPR consent'), false]], L('Design onesto.', 'Honest design.')),
        ]),
        lesson('service', L('Service design e strategia', 'Service design and strategy'), [
            P('Il **service design** guarda oltre lo schermo: un’esperienza nasce anche da persone, processi e sistemi che l’utente non vede. Il **service blueprint** la mostra su più livelli: **azioni dell’utente**, **front stage** (ciò che vede: app, commesso), **back stage** (personale e processi dietro le quinte), **processi di supporto** (sistemi, fornitori), separati dalla **linea di visibilità**.', '**Service design** looks beyond the screen: an experience also comes from people, processes and systems the user does not see. The **service blueprint** shows it in layers: **user actions**, **front stage** (what they see: app, clerk), **back stage** (staff and processes behind the scenes), **support processes** (systems, suppliers), separated by the **line of visibility**.'),
            P('La **strategia UX** collega i bisogni degli utenti agli obiettivi dell’azienda: una **visione** di esperienza, principi di design condivisi, una roadmap basata sulle evidenze e la **ricerca continua** (parlare con gli utenti ogni settimana, non una volta l’anno). Con la **ResearchOps** e la **DesignOps** si organizzano strumenti, archivi di insight e processi perché il team cresca senza perdere qualità.', '**UX strategy** connects users’ needs to business goals: an experience **vision**, shared design principles, an evidence-based roadmap and **continuous research** (talking to users every week, not once a year). With **ResearchOps** and **DesignOps** you organise tools, insight repositories and processes so the team grows without losing quality.'),
        ], [
            Q('s1', L('Che cosa separa la linea di visibilità in un blueprint?', 'What does the line of visibility separate in a blueprint?'), [L('Ciò che l’utente vede da ciò che non vede', 'What the user sees from what they do not'), L('Il desktop dal mobile', 'Desktop from mobile'), L('I colori chiari da quelli scuri', 'Light colours from dark ones'), L('Il prezzo dal costo', 'Price from cost')], 0, L('Front stage e back stage.', 'Front stage and back stage.')),
            Q('s2', L('Che cosa guarda il service design?', 'What does service design look at?'), [L('Persone, processi e sistemi oltre lo schermo', 'People, processes and systems beyond the screen'), L('Solo l’interfaccia dell’app', 'Only the app interface'), L('Solo il logo', 'Only the logo'), L('Solo il codice', 'Only the code')], 0, L('L’esperienza intera.', 'The whole experience.')),
            Q('s3', L('Che cosa significa ricerca continua?', 'What does continuous research mean?'), [L('Parlare con gli utenti regolarmente', 'Talking to users regularly'), L('Una grande ricerca all’anno', 'One big study a year'), L('Leggere solo le recensioni', 'Only reading reviews'), L('Chiedere al team', 'Asking the team')], 0, L('Ogni settimana, poco alla volta.', 'Every week, a little at a time.')),
        ], task('text', L('Per il ritiro di un farmaco ordinato online, scrivi un elemento per ogni livello del blueprint, nel formato `Utente: ...`, `Front stage: ...`, `Back stage: ...` (anche in inglese `User:`).', 'For collecting a medicine ordered online, write one item for each blueprint layer, in the format `User: ...`, `Front stage: ...`, `Back stage: ...`.'), '', [re('^(utente|user)\s*:\s*\S', L('Azione dell’utente', 'User action')), re('^front stage\s*:\s*\S', L('Front stage', 'Front stage')), re('^back stage\s*:\s*\S', L('Back stage', 'Back stage'))], '', "Utente: mostra il QR in farmacia\nFront stage: il farmacista scansiona il codice e consegna\nBack stage: il magazzino prepara il pacco con il nome del cliente"), [
            dOrder(pSort(), [L('Azioni dell’utente', 'User actions'), 'Front stage', L('Linea di visibilità', 'Line of visibility'), 'Back stage', L('Processi di supporto', 'Support processes')], L('I livelli del blueprint, dall’alto.', 'Blueprint layers, from the top.')),
            dFlash(pFlash(), [[L('Il back stage non è visibile all’utente', 'The back stage is not visible to the user'), true], [L('Il service design riguarda solo le app', 'Service design is only about apps'), false], [L('La strategia UX collega utenti e obiettivi aziendali', 'UX strategy links users and business goals'), true], [L('La DesignOps serve a scegliere i colori', 'DesignOps is for picking colours'), false]], L('Oltre lo schermo.', 'Beyond the screen.')),
        ]),
    ],
];
